  public static SNode copyRecovery(Path file, SModel destination, SNodeId templateId) throws IOException {
    SModel stored = loadRecovery(file);
    SNode original = stored.getNode(templateId);
    if (original == null) {
      throw new IOException("The snapshot does not contain the original template.");
    }
    List<SNode> roots = new ArrayList<SNode>();
    for (SNode root : stored.getRootNodes()) {
      roots.add(root);
    }
    Map<SNode, SNode> copies = new HashMap<SNode, SNode>();
    for (SNode root : CopyUtil.copy(roots, copies)) {
      destination.addRootNode(root);
    }
    TemporaryModels.getInstance().addMissingImports(destination);
    return copies.get(original);
  }
