  private static void preserveWords(Plan plan, List<Block> candidates, Set<SNode> preserved) throws DiffTooBigException {
    List<DiffFragment> differences = ComparisonManager.getInstance().compareChars(plan.before, plan.after, ComparisonPolicy.DEFAULT, new EmptyProgressIndicator());
    String[] oldLines = plan.before.split("\n", -1);
    int[] starts = new int[oldLines.length];
    for (int i = 1; i < starts.length; i++) {
      starts[i] = starts[i - 1] + oldLines[i - 1].length() + 1;
    }
    for (Block block : candidates) {
      if (!("Line".equals(block.node.getConcept().getName())) || preserved.contains(block.node) || block.start >= starts.length) {
        continue;
      }
      int column = block.prefix.length();
      for (SNode word : children(block.node, "words")) {
        String text = ("Tab".equals(word.getConcept().getName()) ? "\t" : property(word, "name"));
        text = (text == null ? "" : text);
        int start = starts[block.start] + column;
        int end = start + text.length();
        column += text.length();
        if (start == end || end > plan.before.length()) {
          continue;
        }
        int oldOffset = 0;
        int newOffset = 0;
        int mapped = -1;
        for (DiffFragment difference : differences) {
          if (start >= oldOffset && end <= difference.getStartOffset1()) {
            mapped = newOffset + start - oldOffset;
            break;
          }
          oldOffset = difference.getEndOffset1();
          newOffset = difference.getEndOffset2();
        }
        if (mapped < 0 && start >= oldOffset) {
          mapped = newOffset + start - oldOffset;
        }
        if (mapped < 0 || mapped + text.length() > plan.after.length() || !(text.equals(plan.after.substring(mapped, mapped + text.length())))) {
          continue;
        }
        int row = 0;
        int rowStart = 0;
        for (int offset = 0; offset < mapped; offset++) {
          if (plan.after.charAt(offset) == '\n') {
            row++;
            rowStart = offset + 1;
          }
        }
        boolean covered = false;
        for (Block reused : plan.reuse) {
          if (row >= reused.newStart && row < reused.newStart + reused.end - reused.start) {
            covered = true;
          }
        }
        if (!(covered)) {
          plan.words.add(new Piece(word, row, mapped - rowStart, mapped - rowStart + text.length()));
          descendants(word, preserved);
        }
      }
    }
  }
  private static void appendRange(SNode target, SNode source, int start, int end) {
    int column = 0;
    for (SNode word : children(source, "words")) {
      boolean tab = "Tab".equals(word.getConcept().getName());
      String text = (tab ? "\t" : property(word, "name"));
      text = (text == null ? "" : text);
      int from = Math.max(0, start - column);
      int to = Math.min(text.length(), end - column);
      if (from < to) {
        SNode copy = CopyUtil.copy(word);
        if (!(tab)) {
          setProperty(copy, "name", text.substring(from, to));
        }
        target.addChild(link(target, "words"), copy);
      }
      column += text.length();
    }
  }
  private static boolean isGeneratorAnnotation(SNode node) {
    SConcept concept = node.getConcept();
    while (concept != null) {
      if ("jetbrains.mps.lang.generator".equals(concept.getLanguage().getQualifiedName())) {
        return true;
      }
      concept = concept.getSuperConcept();
    }
    return false;
  }
